import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    adj = {}
    diff = {}
    for i in range(n):
        a = int(data[1 + 2 * i])
        b = int(data[2 + 2 * i])
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, [])
        diff[a] = diff.get(a, 0) + 1
        diff[b] = diff.get(b, 0) - 1
    start = None
    for v, d in diff.items():
        if d == 1:
            start = v
    if start is None:
        start = min(v for v in adj if adj[v])
    for v in adj:
        adj[v].sort(reverse=True)
    stack = [start]
    path = []
    while stack:
        u = stack[-1]
        if adj[u]:
            stack.append(adj[u].pop())
        else:
            path.append(stack.pop())
    path.reverse()
    out = []
    for i in range(len(path) - 1):
        out.append('%d %d' % (path[i], path[i + 1]))
    print('\n'.join(out))

main()

