def gen(rng):
    def fmt(prs):
        prs = list(prs)
        rng.shuffle(prs)
        return str(len(prs)) + '\n' + '\n'.join('%d %d' % (a, b) for a, b in prs)

    def walk(V, L, circuit=False):
        used = set()
        u = rng.randrange(V)
        start = u
        path = []
        while len(path) < L:
            t = None
            for _ in range(40):
                c = rng.randrange(V)
                if c != u and (u, c) not in used:
                    t = c
                    break
            if t is None:
                cand = [c for c in range(V) if c != u and (u, c) not in used]
                if not cand:
                    break
                t = rng.choice(cand)
            used.add((u, t))
            path.append((u, t))
            u = t
        if circuit and u != start and (u, start) not in used:
            path.append((u, start))
        return path

    def relabel(prs, V, big):
        if big:
            labels = rng.sample(range(0, 10**9 + 1), V)
        else:
            labels = list(range(V))
            rng.shuffle(labels)
        return [(labels[a], labels[b]) for a, b in prs]

    def exact(V, L, circuit=False):
        while True:
            p = walk(V, L, circuit)
            if len(p) >= L:
                return p[:L] if not circuit else p
            if circuit and len(p) >= L - 1:
                return p

    tests = [fmt([(1, 2)]), fmt([(1, 2), (2, 1)]), fmt([(1, 2), (2, 1), (1, 3), (3, 1)]),
             fmt([(1, 2), (1, 3), (3, 1)]), fmt([(3, 4), (1, 3), (2, 1), (1, 2)]),
             fmt([(0, 10**9), (10**9, 0)]), fmt([(2, 7), (9, 2), (7, 3), (3, 9)]),
             fmt([(1, 2), (2, 3), (3, 1), (1, 4), (4, 5), (5, 1), (1, 6), (6, 1)])]
    for V, L in ((3, 4), (3, 6), (4, 6), (4, 9), (5, 8), (5, 12), (6, 10), (6, 12), (4, 5), (5, 6)):
        p = walk(V, L, circuit=rng.random() < 0.4)
        tests.append(fmt(relabel(p, V, False)))
    for _ in range(4):
        p = walk(5, 12, circuit=True)
        tests.append(fmt(relabel(p, 5, False)))
    tests.append(fmt(relabel(exact(40, 400), 40, True)))
    tests.append(fmt(relabel(exact(100, 1500), 100, False)))
    tests.append(fmt(relabel(exact(100, 5000), 100, False)))
    tests.append(fmt(relabel(exact(2500, 5000), 2500, True)))
    tests.append(fmt(relabel(exact(5001, 5000), 5001, True)))
    tests.append(fmt(relabel(exact(100, 4999, True), 100, True)))
    return tests

